def _read_chain_data(self, cluster: int, count: Optional[int] = None,
                     contiguous: bool = False) -> bytearray:
    veri = bytearray()
    for c in self.chain(cluster, count, contiguous):
        veri += self.dev.read(self.cluster_offset(c), self.cluster_bytes)
