    bayrak degisirse ust dizindeki akis girisi guncellenir.
    """
    cb = self.cluster_bytes
    clusters = list(self._dir_clusters(ref) if clusters is None else clusters)
    if not clusters:
        raise ExFatError(tr("Bozuk dizin kume zinciri"))
